import json

demo_file = '/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-53acb1f1.json'
with open(demo_file, 'r') as f:
    demos = json.load(f)

# GREATER rule: change to 2 if neighbors are equal AND neighbors > cell
def transform_greater(grid):
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if c == 0 or c == len(grid[r]) - 1:
                continue
            val = grid[r][c]
            left = grid[r][c-1]
            right = grid[r][c+1]
            if left == right and left != val and left > val:
                result[r][c] = 2
    return result

# LESS rule: change to 2 if neighbors are equal AND neighbors < cell
def transform_less(grid):
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if c == 0 or c == len(grid[r]) - 1:
                continue
            val = grid[r][c]
            left = grid[r][c-1]
            right = grid[r][c+1]
            if left == right and left != val and left < val:
                result[r][c] = 2
    return result

print("Testing GREATER and LESS rules (all original neighbors):")
for name, fn in [("GREATER", transform_greater), ("LESS", transform_less)]:
    print(f"\n{name}:")
    for i, demo in enumerate(demos):
        inp = demo['input']
        out = demo['output']
        result = fn(inp)
        match = result == out
        status = "✓" if match else "✗"
        print(f"  Demo {i+1}: {status}")

