# Verify position-based rule on all DEMOs
import json
demo_file = '/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-53acb1f1.json'
with open(demo_file, 'r') as f:
    demos = json.load(f)

def transform_lr_position_based(grid):
    """L→R sequential but only at ODD positions"""
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if c == 0 or c == len(grid[r]) - 1:
                continue
            if c % 2 == 0:  # Only odd positions
                continue
            val = grid[r][c]
            left = result[r][c-1]
            right = grid[r][c+1]
            if left == right and left != val and left < val:
                result[r][c] = 2
    return result

print("Testing position-based rule on all DEMOs:")
for demo_idx in range(3):
    inp = demos[demo_idx]['input']
    out = demos[demo_idx]['output']

    res = transform_lr_position_based(inp)
    all_match = True
    mismatches = []
    for r in range(len(inp)):
        if res[r] != out[r]:
            all_match = False
            for c in range(len(out)):
                if res[r][c] != out[r][c]:
                    mismatches.append((r, c, res[r][c], out[r][c]))
                    if len(mismatches) >= 3:
                        break
            if len(mismatches) >= 3:
                break

    status = "✓" if all_match else f"✗ ({len(mismatches)} diffs)"
    print(f"Demo {demo_idx}: {status}")
    if mismatches:
        print(f"  Mismatches: {mismatches[:5]}")

# If position-based fails on some demos, let me consider EVEN positions vs ALL positions
